import concurrent.futures,copy,hashlib,json,os,pathlib,socket,subprocess,sys,time,urllib.parse,urllib.request,zipfile
import sk,p2,p3
HOSTS={'tetss-prague-ip2-test':('109.248.43.149','Sky2'),'tetss-prague-ip3-test':('109.248.43.30','Sky3')}
assert os.geteuid()==0 and socket.gethostname() in HOSTS,'Wrong target host'
sk.IP,LABEL=HOSTS[socket.gethostname()]
assert sk.IP in sk.run(['hostname','-I']).split(),'IP mismatch'
ROOT=pathlib.Path('/root/skylon-new');CONF=pathlib.Path('/etc/skylon-new')
assert not ROOT.exists() and not CONF.exists(),'Existing configuration: preserve credentials'
for forbidden in ['/etc/xray','/usr/local/etc/xray','/etc/x-ui','/etc/sing-box']:
    assert not pathlib.Path(forbidden).exists(),'Existing VPN installation'
listeners=sk.run(['ss','-H','-lntup'])
for port in [80,443,5443,6443,2443,8388,8443]:
    assert not any(':'+str(port)+' ' in x for x in listeners.splitlines()),'Port occupied'
ROOT.mkdir(mode=0o700);CONF.mkdir(mode=0o700);sk.WEB.mkdir(parents=True,exist_ok=True);sk.WEB.chmod(0o755)
sk.ROOT=ROOT;p2.ROOT=ROOT;p3.ROOT=ROOT;p3.CONF=CONF
UNITS=['skylon-new-xray','skylon-p3-hy27','skylon-p3-hy28']
def status(phase,**kw):
    sk.write_json(sk.WEB/'status.json',{'phase':phase,'time':time.time(),'server':sk.IP,**kw},False);print(phase,flush=True)
def main():
    status('Installing prerequisites')
    env=dict(os.environ,DEBIAN_FRONTEND='noninteractive')
    sk.run(['apt-get','update','-qq'],env=env,timeout=180)
    sk.run(['apt-get','install','-y','-qq','curl','ca-certificates','python3-cryptography'],env=env,timeout=180)
    status('Verifying official binaries')
    archive=ROOT/'xray.zip';urllib.request.urlretrieve(sk.XRAY_URL,archive)
    assert hashlib.sha256(archive.read_bytes()).hexdigest()==sk.XRAY_SHA256
    with zipfile.ZipFile(archive) as z:pathlib.Path(p2.XR).write_bytes(z.read('xray'))
    pathlib.Path(p2.XR).chmod(0o755)
    hyfile=ROOT/'hysteria';urllib.request.urlretrieve(p2.HY_URL,hyfile)
    assert hashlib.sha256(hyfile.read_bytes()).hexdigest()==p2.HY_SHA
    pathlib.Path(p2.HY).write_bytes(hyfile.read_bytes());pathlib.Path(p2.HY).chmod(0o755)
    hy,server,extra=p3.generate()
    base,original=sk.make_configs()
    server['inbounds'] += [x for x in base['inbounds'] if x['port'] in [443,8388]]
    bynum={x['number']:x for x in extra}
    profiles=[original[0],bynum[29],bynum[32],bynum[30],bynum[31],original[17],bynum[27],bynum[28]]
    names=['Vision Microsoft 443','Vision Google MSS 5443','Trojan REALITY 2443','XHTTP packet-up 6443','XHTTP stream-up 6443','SS chacha20 8388','HY2 Salamander UDP443','HY2 QUIC UDP8443']
    for n,(p,name) in enumerate(zip(profiles,names),1):
        p.update(number=n,name=f'{LABEL} Prague {n:02d} {name}')
        p['uri']=p['uri'].split('#')[0]+'#'+urllib.parse.quote(p['name'])
    sk.write_json(CONF/'xray.json',server)
    sk.run([p2.XR,'run','-test','-c',str(CONF/'xray.json')])
    for p in profiles:
        if p['protocol']!='Hysteria2':
            sk.write_json(ROOT/'validate.json',sk.client_config(p,19000+p['number']))
            sk.run([p2.XR,'run','-test','-c',str(ROOT/'validate.json')])
    (ROOT/'validate.json').unlink(missing_ok=True)
    common='''Restart=on-failure
RestartSec=3
DynamicUser=yes
AmbientCapabilities=CAP_NET_BIND_SERVICE
CapabilityBoundingSet=CAP_NET_BIND_SERVICE
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
MemoryMax=192M
LimitNOFILE=32768
[Install]
WantedBy=multi-user.target
'''
    for n,cfg in hy:
        sk.write_json(CONF/f'hy{n}.json',cfg)
        pathlib.Path(f'/etc/systemd/system/skylon-p3-hy{n}.service').write_text(f'''[Unit]
Description={LABEL} Hysteria2 direct test
After=network-online.target
[Service]
LoadCredential=config.json:{CONF}/hy{n}.json
LoadCredential=cert.pem:{CONF}/cert.pem
LoadCredential=key.pem:{CONF}/key.pem
ExecStart={p2.HY} server -c %d/config.json
'''+common)
    pathlib.Path('/etc/systemd/system/skylon-new-xray.service').write_text(f'''[Unit]
Description={LABEL} Xray direct tests
After=network-online.target
[Service]
LoadCredential=config.json:{CONF}/xray.json
ExecStart={p2.XR} run -c %d/config.json
'''+common)
    pathlib.Path('/etc/systemd/system/skylon-delivery.service').write_text('''[Unit]
Description=Encrypted test result delivery
After=network-online.target
[Service]
DynamicUser=yes
ExecStart=/usr/bin/python3 -m http.server 80 --bind 0.0.0.0 --directory /var/lib/skylon-delivery
AmbientCapabilities=CAP_NET_BIND_SERVICE
CapabilityBoundingSet=CAP_NET_BIND_SERVICE
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
RestrictAddressFamilies=AF_INET AF_UNIX
RuntimeMaxSec=14400
''')
    sk.run(['systemctl','daemon-reload'])
    sk.run(['systemd-run','--unit=skylon-new-rollback','--on-active=20m','/bin/systemctl','stop',*UNITS])
    sk.run(['systemctl','start','skylon-delivery',*UNITS])
    bundle={'server':sk.IP,'label':LABEL,'profiles':profiles,'created':time.time(),'scope':'server loopback to public HTTPS file; external Megafon acceptance pending'}
    sk.write_json(ROOT/'bundle.json',bundle);p3.export(bundle)
    for p in profiles:
        status('Testing profile',number=p['number']);p['test']=p2.transfer(p);p3.export(bundle)
        assert p['test']['passed'],f"Transfer failed: {p['number']}"
    status('Minute-long transfers')
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        for p,r in zip(profiles,pool.map(lambda p:p2.transfer(p,True),profiles)):
            p['sustained_test']=r;p3.export(bundle)
    assert all(p['sustained_test']['passed'] for p in profiles),'Sustained test failed'
    for unit in UNITS:assert sk.run(['systemctl','is-active',unit]).strip()=='active'
    sk.run(['systemctl','enable',*UNITS]);sk.run(['systemctl','stop','skylon-new-rollback.timer'])
    bundle['units']={u:sk.run(['systemctl','is-active',u]).strip() for u in UNITS}
    bundle['memory']=sk.run(['free','-m']);bundle['complete']=True
    sk.write_json(ROOT/'bundle.json',bundle);p3.export(bundle);status('Complete',passed=8,sustained_passed=8)
try:main()
except Exception as e:
    subprocess.run(['systemctl','stop',*UNITS],capture_output=True)
    status('Failed',error=type(e).__name__);print(str(e)[:160],flush=True);raise
